import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, throwError, BehaviorSubject } from 'rxjs';
import { catchError, tap } from 'rxjs/operators';
import { Carrito, ProductoCarrito } from '../models/carrito';

@Injectable({
  providedIn: 'root'
})
export class CarritoService {

  private readonly URL = 'http://localhost:3000/api/carrito';

  // BehaviorSubject para mantener el estado actual del carrito
  private carritoSubject = new BehaviorSubject<Carrito>(new Carrito());

  // Observable para que los componentes se suscriban y reciban actualizaciones
  carrito$ = this.carritoSubject.asObservable();

  constructor(private http: HttpClient) {}

  obtenerCarrito(email: string): Observable<Carrito> {
    const url = `${this.URL}/${email}`;
    return this.http.get<Carrito>(url)
      .pipe(
        catchError(this.handleError),
        tap((carrito: Carrito) => {
          this.carritoSubject.next(carrito); // Actualiza el estado del carrito
        })
      );
  }

  agregarAlCarrito(producto: ProductoCarrito): Observable<any> {
    return this.http.post(`${this.URL}/agregar`, producto)
      .pipe(
        catchError(this.handleError),
        tap((res) => {
          // Actualiza el estado del carrito después de agregar un producto
          this.obtenerCarrito(producto.emailUsuario).subscribe();
        })
      );
  }

  eliminarDelCarrito(idProducto: string): Observable<Carrito> {
    return this.http.delete<Carrito>(`${this.URL}/${idProducto}`)
      .pipe(
        catchError(this.handleError),
        tap(() => {
          // Actualiza el estado del carrito después de eliminar un producto
          this.obtenerCarrito(this.carritoSubject.value.emailUsuario).subscribe();
        })
      );
  }

  vaciarCarrito(): Observable<Carrito> {
    return this.http.delete<Carrito>(`${this.URL}/vaciar`)
      .pipe(
        catchError(this.handleError),
        tap(() => {
          // Actualiza el estado del carrito después de vaciarlo
          this.obtenerCarrito(this.carritoSubject.value.emailUsuario).subscribe();
        })
      );
  }

  private handleError(error: any): Observable<any> {
    console.error('Ocurrió un error', error);
    return throwError(error);
  }
}
